// Tap RFID (akses berhasil) -> nyalakan semua unit ruangan ini lewat
// endpoint HTTP yang sama dipakai backend (FMIPA-CONTROL-HUB.json),
// source "door_access" supaya UG65 tahu ini trigger pintu (jendela 25
// menit), bukan perintah Web biasa (30 menit).
var classKey = msg.classKey;
msg.method = "POST";
msg.url = "http://127.0.0.1:1880/api/" + classKey;
msg.payload = { state: "on", source: "door_access" };
msg.headers = { "content-type": "application/json" };
return msg;

// Kirim event akses (Major 5/Minor 1 = verifikasi sukses) ke Web sebagai alert.
// X-Tenant WAJIB -- panggilan ini langsung ke backend (bukan lewat hub),
// tanpa header ini resolveTenant() jatuh ke DEFAULT_TENANT fakultas lain.
var classCode = msg.classCode || msg.classKey;
var p = msg.payload || {};

msg.method = "POST";
msg.url = "http://127.0.0.1:5001/api/v1/alerts/device-event";
msg.payload = Object.assign({}, p, {
    eventDescription: p.eventDescription || "Akses berhasil (Major 5 / Minor 1)",
    doorNo: p.doorNo,
    serialNo: p.serialNo,
    currentVerifyMode: p.currentVerifyMode,
    time: p.time || new Date().toISOString(),
    room: classCode,
    source: "FMIPA-ACCESS-CONTROL." + classCode
});
msg.headers = { "content-type": "application/json", "x-tenant": "fmipa" };
return msg;

// Web/Node-RED sesekali sempat tidak terjangkau sesaat. Coba lagi
// otomatis (maks 3x, jeda 2 detik) sebelum menyerah diam-diam.
msg._retryCount = (msg._retryCount || 0) + 1;
if (msg._retryCount > 3) {
    node.warn("Tidak terjangkau setelah 3x percobaan (access-control): " + (msg.error && msg.error.message));
    return null;
}
return msg;

// Terminal ini sudah di-filter Major 5 di node config-nya, tapi Minor
// perlu dicek manual di sini (samakan dengan pola Major5+Minor1 = 
// "verifikasi akses berhasil" yang dipakai flow FIP).
var p = msg.payload || {};
if (String(p.major) !== "5" || String(p.minor) !== "1") return null;

msg.classKey = "c140402";
msg.classCode = "C14.04.02";
return msg;

